class ArmPowerCommands:
    """Power, fault recovery and stop, which need no lease; a subclass supplies `_run_command`."""

    async def _run_command(
        self,
        command: "StationCommand",
        *,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        raise NotImplementedError

    async def enable(self, *, expected_revision: int | None = None) -> "CommandResult":
        """Preflight, then power the motors holding their present pose."""
        return await self._run_command(
            EnableCommand(), expected_revision=expected_revision
        )

    async def approve_recovery(
        self, *, expected_revision: int | None = None
    ) -> "CommandResult":
        """Approve recovery after inspecting and supporting the arm."""
        return await self._run_command(
            ApproveRecoveryCommand(), expected_revision=expected_revision
        )

    async def disable(self, *, expected_revision: int | None = None) -> "CommandResult":
        """Turn torque off where the arm is; an unsupported arm will fall."""
        return await self._run_command(
            DisableCommand(), expected_revision=expected_revision
        )

    async def stop(self, *, expected_revision: int | None = None) -> "CommandResult":
        """End the active motion with outcome stopped and hold where the arm is.
        Anyone may send it, whoever holds the lease.
        """
        return await self._run_command(
            StopCommand(), expected_revision=expected_revision
        )

    async def clear_fault(
        self, *, expected_revision: int | None = None
    ) -> "CommandResult":
        """Acknowledge a fault; the arm is already disabled."""
        return await self._run_command(
            ClearFaultCommand(), expected_revision=expected_revision
        )


class ArmMotionCommands:
    """The commands that move the arm, which need the lease; a subclass supplies `_run_command`."""

    async def _run_command(
        self,
        command: "StationCommand",
        *,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        raise NotImplementedError

    async def move_to_joints(
        self,
        joints: list[float],
        *,
        max_joint_speed: float | None = None,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        """Move to joint angles, one per joint in the state's order.

        `max_joint_speed`: Peak joint speed in rad/s; clamped to the profile's maximum.
        """
        return await self._run_command(
            MoveToJointsCommand(joints=joints, max_joint_speed=max_joint_speed),
            expected_revision=expected_revision,
        )

    async def move_to_pose(
        self,
        position: list[float],
        orientation: GraspOrientation | QuaternionOrientation,
        *,
        max_joint_speed: float | None = None,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        """Move the tool to a world position and orientation."""
        return await self._run_command(
            MoveToPoseCommand(
                position=position,
                orientation=orientation,
                max_joint_speed=max_joint_speed,
            ),
            expected_revision=expected_revision,
        )

    async def follow_path(
        self,
        waypoints: list[JointsWaypoint | PoseWaypoint],
        *,
        max_joint_speed: float | None = None,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        """Waypoints are corners: the arm comes to rest and settles at each one."""
        return await self._run_command(
            FollowPathCommand(waypoints=waypoints, max_joint_speed=max_joint_speed),
            expected_revision=expected_revision,
        )

    async def stream_joints(
        self,
        joints: list[float],
        *,
        gripper_opening: float | None = None,
        max_joint_speed: float | None = None,
        stream_command_id: str | None = None,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        """Stream trajectory destinations. The first goal, without
        `stream_command_id`, starts a stream when the arm is holding; later goals
        carry the command id it returned. Each cycle the arm moves toward the
        newest goal at up to the first goal's speed. The stream ends stopped when
        goals stop arriving, on stop, or on a trip.

        `gripper_opening`: The gripper's newest target, 0 closed to 1 open, if the stream drives it.
        """
        return await self._run_command(
            StationStreamJointsCommand(
                joints=joints,
                gripper_opening=gripper_opening,
                max_joint_speed=max_joint_speed,
                stream_command_id=stream_command_id,
            ),
            expected_revision=expected_revision,
        )

    async def set_gripper(
        self,
        opening: float,
        *,
        max_joint_speed: float | None = None,
        expected_revision: int | None = None,
    ) -> "CommandResult":
        """Open or close the gripper, 0 closed to 1 open, whether the arm is holding
        or moving. It completes on arrival or on contact.

        `max_joint_speed`: Peak gripper speed in rad/s; uses the arm default and maximum.
        """
        return await self._run_command(
            StationSetGripperCommand(opening=opening, max_joint_speed=max_joint_speed),
            expected_revision=expected_revision,
        )
